mapper.select:
select   
order by c.created_at desc, c.contain_id desc
limit #{limit}

select lot_id, lot_no, item_id, origin, qty_created, unit_cd, occurred_at
  from lot_master
 where item_id = #{itemId} and occurred_at >= #{from} and occurred_at < #{to}
 order by occurred_at, lot_id
 limit #{limit}

select lot_id, lot_no, item_id, origin, qty_created, unit_cd, occurred_at
  from lot_master
 where lot_id in #{id}
